<?php

/**
 * Mengubah "Fabian Syah Al Ghiffari" menjadi "FS"
 */
if (!function_exists('getInitials')) {
    function getInitials($name)
    {
        $words = explode(' ', $name);
        $initials = '';

        if (count($words) >= 2) {
            $initials = strtoupper(substr($words[0], 0, 1) . substr($words[1], 0, 1));
        } else if (count($words) == 1) {
            $initials = strtoupper(substr($words[0], 0, 2));
        } else {
            $initials = '??';
        }

        return $initials;
    }
}

/**
 * PStore Base64 Favicon Data URI (Bypasses CDN cache & missing file errors)
 */
if (!function_exists('pstoreFaviconDataUri')) {
    function pstoreFaviconDataUri()
    {
        return 'data:image/png;base64,';
    }
}

/**
 * PStore Horizontal Header Logo Data URI (Bypasses Hostinger 404/302 redirects)
 */
if (!function_exists('pstoreLogoHorizontalDataUri')) {
    function pstoreLogoHorizontalDataUri()
    {
        return 'data:image/png;base64,';
    }
}
